INSERT INTO "test_plans" ("id", "title", "description", "version", "environment", "status", "scope", "requirements", "projectId", "createdAt", "updatedAt") VALUES
  ('9bcbe93b-78e4-42e7-aabb-fecf32c8f547', 'Core Banking - Smoke Test Plan (v1.0)', 'Kritik bankacılık operasyonları için yüksek öncelikli (@smoke) hızlı duman testi planı.', 'v1.0.0', 'UAT', 'ACTIVE', 'TESTGROUP1, TESTGROUP2, TESTGROUP3 altındaki tüm @smoke etiketli senaryolar (Login, Para Transferi, Müşteri vb.)', 'Tüm kritik bankacılık çekirdek fonksiyonlarının temel yetkilendirme, sorgulama ve işlem yapabilme yeteneğinin doğrulanması.', '47c96c70-2d69-4509-b480-cbe013f74153', '2026-09-01T12:56:38.252Z', '2026-09-01T12:56:38.252Z'),
  ('d0e686df-913f-4730-972f-d73e163db619', 'Core Banking - Full Regression Test Plan (v1.0)', '31 Modül ve 700+ BDD senaryosunu içeren uçtan uca tam regresyon test planı.', 'v1.0.0', 'UAT', 'ACTIVE', 'Kasa, Hazine, Dış Ticaret, Krediler, Hesap, Para Transferi, Müşteri, Ayarlar, DBS, Yasal Takip, Kredi Kartları vb.', 'Sprint sonu ve büyük sürüm öncesi tüm bankacılık iş kurallarının ve entegrasyonlarının doğrulanması.', '47c96c70-2d69-4509-b480-cbe013f74153', '2026-09-01T12:56:38.255Z', '2026-09-01T12:56:38.255Z'),
  ('1418ab8a-30b6-4be9-b6b1-e6c81620d01c', 'Core Banking - Krediler, Hazine & Dış Ticaret Planı', 'Bireysel/Kurumsal Krediler, Hazine, Dış Ticaret ve Teminat Mektubu modüllerinin doğrulanması.', 'v1.0.0', 'STAGING', 'ACTIVE', 'TESTGROUP1 (Hazine, Dış Ticaret, Kasa, Krediler) ve TESTGROUP2 (Kurumsal Krediler, Teminat Mektubu, Limit, Yatırım)', 'Kredi hesaplama, kullandırım, limit tahsis, teminat bağlama ve döviz/hazine işlem kontrolleri.', '47c96c70-2d69-4509-b480-cbe013f74153', '2026-09-01T12:56:38.257Z', '2026-09-01T12:56:38.257Z'),
  ('12ab219d-a2b3-46c7-8264-113d5e187cd3', 'Core Banking - Para Transferleri, Talimat & Muhasebe Planı', 'EFT, Havale, PÖS, Talimat yönetimi ve Muhasebe fiş kayıtlarının uçtan uca doğrulanması.', 'v1.0.0', 'STAGING', 'ACTIVE', 'TESTGROUP2: 12_Para_Transferi, 11_Muhasebe, 19_Talimat, 03_Account', 'Hesaplar arası transfer, PÖS banka/şube işlemleri, muhasebeleştirme ve talimat akış kontrolleri.', '47c96c70-2d69-4509-b480-cbe013f74153', '2026-09-01T12:56:38.258Z', '2026-09-01T12:56:38.258Z'),
  ('50093518-80d1-4b27-b083-9011e42c65e0', 'Core Banking - Müşteri, Güvenlik & Sistem Ayarları Planı', 'Müşteri açılış/güncelleme, yetki grupları, audit logları ve parametrik sistem ayarları testi.', 'v1.0.0', 'STAGING', 'ACTIVE', 'TESTGROUP3: 02_Customer, 05_Ayarlar, 22_Yasal_Takip, 25_YasalBildirimler, 26_Haberlesme', 'Müşteri bilgi güvenliği, kullanıcı yetki matrisi, kilitli işlemler ve yasal bildirim formatlarının doğrulanması.', '47c96c70-2d69-4509-b480-cbe013f74153', '2026-09-01T12:56:38.260Z', '2026-09-01T12:56:38.260Z'),
  ('b7bf2241-2149-4fde-8925-7c135477dd0a', 'iOS Mobile - Smoke Test Plan (v1.0)', 'Kritik iOS mobil bankacılık akışlarının (@Smoke & @Critical) hızlı duman testi planı.', 'v1.0.0', 'UAT', 'ACTIVE', 'Anasayfa, Before Login, Para Transferleri, Fast, Kredi Kartı ve Hesaplar (@Smoke & @Critical senaryoları)', 'iOS uygulamasının açılış, kullanıcı girişi, hesap özetleri ve transfer fonksiyonlarının doğrulanması.', 'a08c8625-5586-48ef-b4b3-a7cd905b858c', '2026-09-01T14:13:27.802Z', '2026-09-01T14:13:27.802Z'),
  ('a82c4042-0e37-4ea7-b098-df7997d24971', 'iOS Mobile - Full Regression Test Plan (v1.0)', '18 Modül ve 111 iOS BDD senaryosunu içeren uçtan uca mobil regresyon test planı.', 'v1.0.0', 'UAT', 'ACTIVE', 'Anasayfa, Profil & Ayarlar, Vadesiz/Vadeli/Salkım Hesaplar, Para Transferi, Talimatlar, Kolay Adres, Limitler, Ödemeler, Kredi Kartı, Döviz, FAST, Karekod, Öde-İste vb.', 'iOS App Store sürüm çıkışları ve Sprint sonlarında tüm mobil iş akışlarının uçtan uca regresyon onayı.', 'a08c8625-5586-48ef-b4b3-a7cd905b858c', '2026-09-01T14:13:27.810Z', '2026-09-01T14:13:27.810Z'),
  ('214613a1-8a26-4794-89df-98d4818500b9', 'iOS Mobile - Hesaplar, Transfer & Ödemeler Planı', 'Vadesiz, Vadeli, Salkım hesaplar, Para Transferi, FAST, Kolay Adres ve Fatura/Ödeme işlemleri testi.', 'v1.0.0', 'STAGING', 'ACTIVE', 'Hesaplar (Vadesiz, Vadeli, Salkım), TG05_ParaTransferleri, TG13_Fast_Islemleri, TG07_KolayAdres, TG09_Odemeler, TG10_HesapHareketleri', 'Hesap açılış/kapama, para transferi, FAST işlem limitleri, alıcı kaydetme ve dekont kontrolleri.', 'a08c8625-5586-48ef-b4b3-a7cd905b858c', '2026-09-01T14:13:27.819Z', '2026-09-01T14:13:27.819Z'),
  ('91d97894-ddd6-4858-b8d5-5387a95b677e', 'iOS Mobile - Kartlar, Limit & Döviz İşlemleri Planı', 'Kredi kartı işlemleri, limit yönetimi, döviz alış/satış, karekod ve öde-iste akışlarının doğrulanması.', 'v1.0.0', 'STAGING', 'ACTIVE', 'TG11_KrediKarti, TG08_LimitIslemleri, TG12_DovizIslemleri, TG14_KareKod_Islemleri, TG15_OdeIste_Islemleri, TG06_Talimatlar', 'Kart borç ödeme, limit artış talebi, döviz kuru hesaplama, QR kod ile para çekme/ödeme.', 'a08c8625-5586-48ef-b4b3-a7cd905b858c', '2026-09-01T14:13:27.824Z', '2026-09-01T14:13:27.824Z'),
  ('0985d4ed-d3e9-4027-826d-c2ec3823f1a9', 'iOS Mobile - Kimlik, Profil & Anasayfa Güvenlik Planı', 'Login öncesi güvenlik, biyometrik giriş, profil ayarları, tanımlı alıcılar ve dashboard bileşenleri testi.', 'v1.0.0', 'STAGING', 'ACTIVE', 'TG21_Before_Login, TG01_Anasayfa, TG02_ProfilveAyarlar, TG04_TanimliAlicilar', 'Şifre değiştirme, FaceID/TouchID entegrasyonu, bildirim tercihleri ve tanımlı IBAN listeleri.', 'a08c8625-5586-48ef-b4b3-a7cd905b858c', '2026-09-01T14:13:27.829Z', '2026-09-01T14:13:27.829Z');
